import * as React from "react";
import { cx } from "./cx";

export const Card = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  function Card({ className, ...props }, ref) {
    return <div ref={ref} className={cx("rs-card", className)} {...props} />;
  },
);

export function CardInner({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) {
  return <div className={cx("rs-card-in", className)} {...props} />;
}

export function CardLabel({ className, ...props }: React.HTMLAttributes<HTMLSpanElement>) {
  return <span className={cx("rs-card-label", className)} {...props} />;
}

export function CardTitle({ className, ...props }: React.HTMLAttributes<HTMLHeadingElement>) {
  return <h3 className={cx("rs-card-title", className)} {...props} />;
}

export function CardBody({ className, ...props }: React.HTMLAttributes<HTMLParagraphElement>) {
  return <p className={cx("rs-card-body", className)} {...props} />;
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Card: typography stack. No outline. Chrome-square. ── */
.rs-card{
  --rs-out:0;
  --rs-gap:20px;
  --rs-in:max(0px,calc(var(--rs-out) - var(--rs-gap)));
  border:0;
  border-radius:var(--rs-out);
  padding:0;
  max-width:360px;
  background:none;
  box-shadow:none
}
.rs-card-label{font-size:12px;font-weight:600;color:var(--accent);letter-spacing:-.01em;display:block;margin-bottom:6px}
.rs-card-title{font-size:17px;font-weight:600;color:var(--text);letter-spacing:-.02em;margin:0 0 8px}
.rs-card-body{font-size:14px;color:var(--text-secondary);font-weight:500;letter-spacing:-.01em;line-height:1.6;margin:0}
.rs-card-in{
  box-sizing:border-box;
  border:0;
  border-radius:var(--rs-in);
  min-height:0;
  padding:0;
  background:none
}
.rs-card .rs-btn-primary,.rs-card .rs-btn-ghost,.rs-card .rs-input,.rs-card .rs-textarea{border-radius:var(--rs-in)}
.rs-card .rs-btn-group{--rs-out:var(--rs-in);border-radius:var(--rs-out)}
